def gcd(a, b):
	if a == 0:
		return b
	return gcd(b % a, a)
for _ in range(int(input())):
	n = int(input())
	a = []
	mod = 998244353
	for i in range(n):
		(x, y) = map(int, input().split())
		a.append((x, y))
	a.sort()
	if n == 1:
		print((pow(2, a[0][1], mod) - 2) % mod)
		continue
	prefixlcm = []
	lcm = 1
	for i in range(n):
		lcm = lcm * a[i][0] // gcd(lcm, a[i][0])
		prefixlcm.append(lcm)
	suffixgcd = [0] * n
	g = 0
	for i in range(n - 1, -1, -1):
		g = gcd(g, a[i][0])
		suffixgcd[i] = g
	res = 0
	b = 0
	for i in range(n - 1):
		if prefixlcm[i] > 1000000000.0:
			b = 1
			break
		if suffixgcd[i] % prefixlcm[i] == 0:
			res = (res + pow(2, a[i][1], mod) - 2) % mod
		if i + 1 < n and suffixgcd[i + 1] % prefixlcm[i] == 0:
			res = (res + 1) % mod
	if not b and suffixgcd[n - 1] % prefixlcm[n - 1] == 0:
		res = (res + pow(2, a[n - 1][1], mod) - 2) % mod
	print(res)
